int N;
int pos_row[1000001], pos_col[1000001]; // position of each viewer
int bit[1001][1002]; // BIT for each row

void update(int row, int col, int val) {
    for (; col <= N; col += col & (-col))
        bit[row][col] += val;
}

int query(int row, int col) {
    int s = 0;
    for (; col > 0; col -= col & (-col))
        s += bit[row][col];
    return s;
}

int main() {
    scanf("%d", &N);
    // Read grid: grid[i][j] = viewer id at row i, col j
    for (int i = 1; i <= N; i++) {
        for (int j = 1; j <= N; j++) {
            int v;
            scanf("%d", &v);
            pos_row[v] = i;
            pos_col[v] = j;
            update(i, j, 1);
        }
    }

    long long ans = 0;
    // Read exit order
    for (int t = 0; t < N * N; t++) {
        int x;
        scanf("%d", &x);
        int r = pos_row[x], c = pos_col[x];
        // Remove x from BIT
        update(r, c, -1);
        // Count viewers in row r with col > c (still seated, already removed x)
        int total_in_row = query(r, N);
        int up_to_c = query(r, c);
        ans += total_in_row - up_to_c;
    }

    printf("%lld\n", ans);
    return 0;
}

