/*
We model the cinema as N rows, each with N seats.

Input format assumed:
- First line: N
- Next N lines: N integers each, the initial seating arrangement.
- Last line (or next N*N integers): the leaving order.

For a viewer x leaving from seat (r, c), every still-seated viewer in the same row
with seat index < c will be crossed and will hate x.

So we need, for each person x in leaving order:
  count how many occupied seats remain to the left of x in x's row,
  add that to the answer,
  then remove x from that row.

This is done with a Fenwick tree per row over the N seat positions.
Total complexity: O(N^2 log N).
*/

typedef long long ll;

typedef struct {
    int n;
    int *bit;
} Fenwick;

static void fenwick_init(Fenwick *f, int n) {
    f->n = n;
    f->bit = (int*)calloc(n + 1, sizeof(int));
}

static void fenwick_add(Fenwick *f, int idx, int val) {
    while (idx <= f->n) {
        f->bit[idx] += val;
        idx += idx & -idx;
    }
}

static int fenwick_sum(Fenwick *f, int idx) {
    int s = 0;
    while (idx > 0) {
        s += f->bit[idx];
        idx -= idx & -idx;
    }
    return s;
}

static void fenwick_free(Fenwick *f) {
    free(f->bit);
}

int main(void) {
    int N;
    if (scanf("%d", &N) != 1) return 0;

    int total = N * N;

    int *rowOf = (int*)malloc((total + 1) * sizeof(int));
    int *colOf = (int*)malloc((total + 1) * sizeof(int));

    Fenwick *rows = (Fenwick*)malloc(N * sizeof(Fenwick));
    for (int i = 0; i < N; ++i) fenwick_init(&rows[i], N);

    for (int r = 1; r <= N; ++r) {
        for (int c = 1; c <= N; ++c) {
            int x;
            scanf("%d", &x);
            rowOf[x] = r;
            colOf[x] = c;
            fenwick_add(&rows[r - 1], c, 1);
        }
    }

    ll ans = 0;
    for (int i = 0; i < total; ++i) {
        int x;
        scanf("%d", &x);
        int r = rowOf[x];
        int c = colOf[x];
        ans += fenwick_sum(&rows[r - 1], c - 1);
        fenwick_add(&rows[r - 1], c, -1);
    }

    printf("%lld\n", ans);

    for (int i = 0; i < N; ++i) fenwick_free(&rows[i]);
    free(rows);
    free(rowOf);
    free(colOf);

    return 0;
}

