        int n = Integer.parseInt(br.readLine().trim());

        int[][] seat = new int[n][n]; // seat[r][c] = viewer id
        int[] row = new int[n*n+1], col = new int[n*n+1];

        for (int r = 0; r < n; r++) {
            StringTokenizer st = new StringTokenizer(br.readLine());
            for (int c = 0; c < n; c++) {
                seat[r][c] = Integer.parseInt(st.nextToken());
                row[seat[r][c]] = r;
                col[seat[r][c]] = c;
            }
        }

        int[] exitOrder = new int[n*n];
        StringTokenizer st = new StringTokenizer(br.readLine());
        for (int i = 0; i < n*n; i++) {
            exitOrder[i] = Integer.parseInt(st.nextToken());
        }

        boolean[][] seated = new boolean[n][n];
        for (boolean[] row2 : seated) Arrays.fill(row2, true);

        long hateCount = 0;

        for (int i = 0; i < n*n; i++) {
            int x = exitOrder[i];
            int r = row[x], c = col[x];

            // Determine exit direction: go to nearest end
            // If c <= n/2 - 1 (0-indexed: closer to left), go left; else go right
            if (c <= (n-1)/2) {
                // go left: pass through cols c-1, c-2, ..., 0
                for (int cc = c-1; cc >= 0; cc--) {
                    if (seated[r][cc]) hateCount++;
                }
            } else {
                // go right: pass through cols c+1, ..., n-1
                for (int cc = c+1; cc < n; cc++) {
                    if (seated[r][cc]) hateCount++;
                }
            }

            seated[r][c] = false;
        }

        System.out.println(hateCount);
    }
}

