public class Main {
    // Fenwick Tree / BIT for prefix sums
    static class Fenwick {
        long[] bit;
        int n;

        Fenwick(int n) {
            this.n = n;
            bit = new long[n + 2];
        }

        void add(int idx, long val) {
            while (idx <= n) {
                bit[idx] += val;
                idx += idx & -idx;
            }
        }

        long sum(int idx) {
            long res = 0;
            while (idx > 0) {
                res += bit[idx];
                idx -= idx & -idx;
            }
            return res;
        }

        long rangeSum(int l, int r) {
            if (l > r) return 0;
            return sum(r) - sum(l - 1);
        }
    }

    public static void main(String[] args) throws Exception {
        FastScanner fs = new FastScanner(System.in);

        int n = fs.nextInt();
        int total = n * n;

        int[] row = new int[total + 1];
        int[] seat = new int[total + 1];

        // Read initial arrangement: n rows, each with n viewers
        for (int i = 1; i <= n; i++) {
            for (int j = 1; j <= n; j++) {
                int x = fs.nextInt();
                row[x] = i;
                seat[x] = j;
            }
        }

        Fenwick[] bits = new Fenwick[n + 1];
        for (int i = 1; i <= n; i++) bits[i] = new Fenwick(n);

        // Initially all seats are occupied
        for (int x = 1; x <= total; x++) {
            bits[row[x]].add(seat[x], 1);
        }

        long ans = 0;

        // Exit order
        for (int k = 0; k < total; k++) {
            int x = fs.nextInt();
            int r = row[x];
            int s = seat[x];

            // People in the same row between seat 1 and s-1 still present
            // will be passed by x when leaving
            ans += bits[r].rangeSum(1, s - 1);

            // x leaves, so remove from occupied seats
            bits[r].add(s, -1);
        }

        System.out.println(ans);
    }

    // Fast input
    static class FastScanner {
        private final InputStream in;
        private final byte[] buffer = new byte[1 << 16];
        private int ptr = 0, len = 0;

        FastScanner(InputStream is) {
            in = is;
        }

        private int read() throws IOException {
            if (ptr >= len) {
                len = in.read(buffer);
                ptr = 0;
                if (len <= 0) return -1;
            }
            return buffer[ptr++];
        }

        int nextInt() throws IOException {
            int c;
            do {
                c = read();
            } while (c <= ' ' && c != -1);

            int sign = 1;
            if (c == '-') {
                sign = -1;
                c = read();
            }

            int val = 0;
            while (c > ' ') {
                val = val * 10 + (c - '0');
                c = read();
            }
            return val * sign;
        }
    }
}

