#include <bits/stdc++.h>
using namespace std;

/*
We have an N x N cinema.
Initial seating is given row by row.
People leave in some order.

If person x leaves from seat (r, c), they move through the row to the aisle.
Any still-seated person between x and the aisle in the same row will be passed by,
thus that person will hate x.

Assume aisle is at the left side of each row:
when person at column c leaves, all occupied seats in columns < c in the same row
will hate them.

We need total number of ordered pairs (x, y) such that y hates x.

Processing in leave order:
For each leaving person x at (row, col), count how many people in that row are still
present in columns [1, col-1]. Add that to answer, then remove x from that seat.

Use Fenwick tree per row to maintain occupied seats.
*/

struct Fenwick {
    int n;
    vector<int> bit;
    Fenwick() {}
    Fenwick(int n): n(n), bit(n + 1, 0) {}
    void add(int idx, int val) {
        for (; idx <= n; idx += idx & -idx) bit[idx] += val;
    }
    int sumPrefix(int idx) const {
        int r = 0;
        for (; idx > 0; idx -= idx & -idx) r += bit[idx];
        return r;
    }
    int rangeSum(int l, int r) const {
        if (l > r) return 0;
        return sumPrefix(r) - sumPrefix(l - 1);
    }
};

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int N;
    cin >> N;

    unordered_map<int, pair<int,int>> pos;
    pos.reserve((size_t)N * N * 2);

    vector<Fenwick> rows(N + 1);
    for (int i = 1; i <= N; ++i) rows[i] = Fenwick(N);

    for (int i = 1; i <= N; ++i) {
        for (int j = 1; j <= N; ++j) {
            int x;
            cin >> x;
            pos[x] = {i, j};
            rows[i].add(j, 1);
        }
    }

    long long ans = 0;
    for (int k = 0; k < N * N; ++k) {
        int x;
        cin >> x;
        auto [r, c] = pos[x];
        ans += rows[r].rangeSum(1, c - 1);
        rows[r].add(c, -1);
    }

    cout << ans << '\n';
    return 0;
}
